# Generated by Descant: acceptance tests.

# frozen_string_literal: true

require "rails_helper"
require "rake"

RSpec.describe "timekeeping:alerts" do
  # "It logs each alert with `company_id`."
  it "logs the reference_unavailable alert under the failing company's company_id and never under a healthy company" do
    Rails.application.load_tasks if Rake::Task.tasks.empty?
    Rake::Task["timekeeping:alerts"].reenable
    TimekeepingOwnership.ensure_initial!
    token = SecureRandom.hex(24)
    env_before = ENV.to_h.slice("TIMEKEEPING_BASE_URL", "TIMEKEEPING_SERVICE_TOKEN")
    ENV["TIMEKEEPING_BASE_URL"] = "http://timekeeping.test"
    ENV["TIMEKEEPING_SERVICE_TOKEN"] = token

    travel_to Time.utc(2026, 5, 1, 12, 7, 0) do
      completed_window = "2026-05-01T12:00:00Z"
      window = ->(writes, unavailable) {
        { "window_start" => completed_window, "writes" => writes, "reference_unavailable" => unavailable,
          "stale_generation" => 0, "latency_ms_sum" => (writes + unavailable) * 10,
          "latency_ms_buckets" => { "25" => writes + unavailable } }
      }
      body = {
        "latency_bucket_bounds_ms" => [25, 50, 100, 200, 300, 500, 1000, 2500, 5000],
        "overflow_bucket" => "inf",
        "total_field" => "writes + reference_unavailable",
        "companies" => [
          { "company_id" => 7, "windows" => [window.call(97, 3)] },
          { "company_id" => 8, "windows" => [window.call(5000, 0)] }
        ]
      }
      stub_request(:get, "http://timekeeping.test/internal/v1/metrics")
        .with(headers: { "Authorization" => "Bearer #{token}" })
        .to_return(status: 200, body: JSON.generate(body), headers: { "Content-Type" => "application/json" })

      output = capture_stdout_for_timekeeping_alerts { Rake::Task["timekeeping:alerts"].invoke }

      expect(output).to match(/alert=reference_unavailable company_id=7\b/)
      expect(output).not_to match(/company_id=8\b/)
      expect(output).not_to include(token)
    end
  ensure
    %w[TIMEKEEPING_BASE_URL TIMEKEEPING_SERVICE_TOKEN].each { |key| ENV[key] = env_before&.fetch(key, nil) }
  end

  def capture_stdout_for_timekeeping_alerts
    original = $stdout
    $stdout = StringIO.new
    yield
    $stdout.string
  ensure
    $stdout = original
  end
end
